mapper.sql:
 		from product as a
 		left join discount b on b.dc_id = a.discount_dc_id
 		where 1=1
		AND a.pd_use = #{shUseNy}
         AND 0 = #{shDelNy}
         AND a.local = #{shlocal}
         AND a.type = #{shtype}
         AND a.brand = #{shbrand}


			AND a.pd_regiDate BETWEEN #{shDateStart} AND #{shDateEnd}
			AND a.pd_modiDate  BETWEEN #{shDateStart} AND #{shDateEnd}



            AND a.pd_id = #{shValue}
            AND a.name LIKE CONCAT('%',#{shValue},'%')

mapper.update:
		update product set
		name = #{name}
		,pd_use = #{pd_use}
		,local = #{local}
		,local_detail = #{local_detail}
		,brand = #{brand}
		,type = #{type}
		,capacity = #{capacity}
		,liquor = #{liquor}
		,fixed_price = #{fixed_price}
		,discountNY = #{discountNY}
		,pd_quantity = #{pd_quantity}
		,pd_modiDate = now()
		,discount_dc_id = 1
        				 #{discount_dc_id}
		WHERE 1=1
		and pd_id = #{pd_id}

mapper.select:
		SELECT COUNT(*)
		FROM product a

  	AND a.local = #{local}
  	AND a.local_detail = #{local_detail}
  	AND a.type = #{type}
  	AND a.fixed_price >= #{minPrice}
  	AND a.fixed_price <= #{maxPrice}
  	AND a.name LIKE CONCAT('%', #{keyword}, '%')
